import java.util.*;
record BusPass(String id,String holder,int route){} interface PassDao{void save(BusPass p);Optional<BusPass> find(String id);List<BusPass> findByRoute(int route);} class InMemoryPassDao implements PassDao{private final Map<String,BusPass> data=new HashMap<>();public void save(BusPass p){data.put(p.id(),p);}public Optional<BusPass> find(String id){return Optional.ofNullable(data.get(id));}public List<BusPass> findByRoute(int r){return data.values().stream().filter(p->p.route()==r).toList();}} public class Main{public static void main(String[]a){PassDao dao=new InMemoryPassDao();dao.save(new BusPass("P1","Mahesh",12));System.out.println(dao.find("P1"));System.out.println(dao.findByRoute(12));}}
